window.NPC_CHUNK_4 = [{"name":"Ilnerik Sivanshin","cr":15,"xp":51200,"race":"Half-Elf","gender":"Male","age_category":"Adult","classes":[{"class":"bard","level":7},{"class":"rogue","level":3}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["elf","human"],"templates_applied":"vampire","init":10,"senses":["darkvision 60 ft.","low-light vision"],"ac":31,"ac_touch":20,"ac_flat_footed":24,"ac_mods":"+5 armor, +3 deflection, +6 Dex, +1 dodge, +6 natural","hp":197,"hd":"13d8+140","hd_value":13,"hp_mods":"fast healing 5","fort":13,"ref":18,"will":7,"save_mods":"+2 vs. enchantments+4 vs. bardic performance, language-dependent, and sonic","defensive_abilities":["channel resistance +4","evasion","live to tell the tale 1/day","trap sense +1"],"dr":"10/magic and silver","immunities":["undead traits"],"resists":["cold 10","electricity 10"],"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"slam +15 (2d4+12)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic music 13 rounds/day","details":"move action- countersong, dirge of doom, distraction, fascinate, inspire competence +3, inspire courage +2, suggestion"},{"type":"blood drain"},{"type":"children of the night"},{"type":"create spawn"},{"type":"dominate","details":"DC 25"},{"type":"energy drain","details":"DC 25"},{"type":"mastermind"},{"type":"sneak attack","details":"+2d6"}],"spellsknown_caster":"bard","spellsknown_caster_level":7,"spellsknown_concentration":16,"spellsknown":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"charm monster"},{"spell":"haste"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"blindness/deafness"},{"spell":"invisibility"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"comprehend languages"},{"spell":"grease"},{"spell":"obscure object"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"know direction"},{"spell":"light"},{"spell":"mage hand"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":22,"dexterity":22,"intelligence":15,"wisdom":10,"charisma":28,"baseatk":8,"cmb":14,"cmd":34,"feats":[{"feat":"Alertness"},{"feat":"Arcane Strike"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Feint"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (slam)"},{"feat":"Whirlwind Attack"}],"skills":[{"skill":"Acrobatics","value":22},{"skill":"Bluff","value":0},{"skill":"Disable Device","value":22},{"skill":"Knowledge (arcana)","value":0},{"skill":"Knowledge (dungeoneering)","value":0},{"skill":"Knowledge (engineering)","value":0},{"skill":"Knowledge (geography)","value":16},{"skill":"Knowledge (history)","value":0},{"skill":"Knowledge (local)","value":23},{"skill":"Knowledge (nature)","value":0},{"skill":"Knowledge (nobility)","value":0},{"skill":"Knowledge (planes)","value":0},{"skill":"Knowledge (religion)","value":23},{"skill":"Linguistics","value":14},{"skill":"Perception","value":30},{"skill":"Perform (oratory)","value":25},{"skill":"Perform (sing)","value":25},{"skill":"Sense Motive","value":0},{"skill":"Stealth","value":30}],"languages":["Common","Ancient Osiriani","Dark Folk","Elven","Infernal","Osiriani","Polyglot","Shadowtongue","Undercommon","Varisian"],"sq":["bardic knowledge +5","deep pockets (300 gp)","gaseous form","improved aid","lore master 1/day","master scribe","pathfinding","rogue talent (weapon training)","shadowless","spider climb","trapfinding","versatile performance (oratory, sing)","well-versed"],"special_abilities":[{"type":"Mastermind","kind":"Su","details":"Ilnerik doesn't possess the usual vampiric ability to change shape. Instead, he can have a number of enslaved spawn totaling four times his Hit Dice (up to 52 spawn at any one time). In addition, he may enter a trance to observe a single spawn's surroundings as if looking through that spawn's eyes, provided the spawn in question is on the same plane. Exercising or ending this ability is a standard action-he can maintain the clairvoyance link as long as he wishes, but while the link persists, Ilnerik is treated as helpless (although he is alerted to any jarring noises, the presence of any visible creature within 5 feet, or any damage that befalls his body). This ability (and many different alternate vampire powers) first appeared in Classic Horrors Revisited. Rod of Shadowy Splendor This magic rod functions identically to a standard rod of splendor, save that the garb it creates is always in the hues of red, white, and black, and the palatial tent it creates contains no food and is dimly lit. This gloom cannot be further darkened or illuminated by any effect less potent than a 5th-level spell."}],"gear":"+3 leather armor, amulet of mighty fists +2, belt of physical might +4 (Strength, Dexterity), ring of protection +3, rod of shadowy splendor, boots of teleportation, 3000 gp in elegant jewelry, master key to locked doors in Walcourt, Totemrix","before_combat":"Ilnerik has an unseen servant active at all times.","during_combat":"Ilnerik orders his unseen servant to trigger the lever to fill both sarcophagi with water, hoping that the peril this places the two women in forces the PCs to split their attention between fighting him and saving Faerlyn and Glynnis. Ilnerik's first act in combat is to cast invisibility on himself, followed by casting haste and inspiring courage before opening battle by making a sneak attack on a foe that can't see through his invisibility. Ilnerik trusts his high Armor Class once battles begin and deliberately lets his foes surround him so he can use Whirlwind Attacks, and uses Arcane Strike and Vital Strike with his slam attacks at all times. He saves his dominate ability and ranged spells to combat foes at range.","morale":"Ilnerik fights until destroyed, at which point he flees under the altar stone to recover, unless the PCs are present, in which case he flees to room F8 if he thinks he can get there without being observed. Unfortunately for Ilnerik, the running water in the numerous canals and sewage tunnels in the area make escaping to other locations more distant relatively impossible.","source":"AP 29, Pathfinder chronicler 3"},{"name":"Guxer","cr":5,"xp":1600,"race":"human","gender":"Male","age_category":"middle age","classes":[{"class":"aristocrat","level":6},{"class":"fighter","level":2}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":13,"ac_touch":10,"ac_flat_footed":13,"ac_mods":"+3 armor","hp":60,"hd":"2d10+6d8+22","hd_value":8,"fort":9,"ref":2,"will":2,"save_mods":"+1 vs. fear","weaknesses":["paranoia"],"speed":[{"type":"land","speed":30}],"melee":"+1 rapier +10 (1d6+3/18-20)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":11,"constitution":14,"intelligence":11,"wisdom":9,"charisma":17,"baseatk":6,"cmb":8,"cmd":18,"feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Persuasive"},{"feat":"Power Attack"},{"feat":"Quick Draw"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Appraise","value":7},{"skill":"Diplomacy","value":12},{"skill":"Intimidate","value":12},{"skill":"Knowledge (nobility)","value":11},{"skill":"Ride","value":11}],"languages":["Common"],"sq":["bravery +1"],"special_abilities":[{"type":"Paranoia","kind":"Ex","details":"Guxer's paranoia imparts a -4 penalty on Charismabased skill checks and Will saves, and he cannot receive benefit from or attempt the aid another action nor can he willingly accept aid (including healing) from another creature unless he makes a DC 17 Will save-otherwise he fights tooth and nail to prevent the \"aid\" (which he perceives as a threat). Lesser restoration has no effect on curing Guxer's paranoia, but restoration reduces the strength so that the nobleman can function relatively normally (enough so that he can treat with the PCs and forge alliances, at least). Greater restoration, heal, limited wish, miracle, or wish immediately cure Guxer completely of his insanity, though he remains depressed and confused by recent events."}],"gear":"+2 padded armor, +1 rapier","during_combat":"Guxer is dejected and depressed, and only fights in self-defense or if he suspects that someone is in league with his brother. In this case, he fights with his rapier while tears of anger stream down his cheeks.","morale":"Guxer feels increasingly that he has little reason to live-if a fight begins, he fights to the death.","source":"AP 30"},{"name":"Zevanxus (aka Delilee)","cr":11,"xp":9600,"race":"doppelganger","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":8}],"alignment":"N","size":"Medium","type":"monstrous humanoid","init":4,"senses":["darkvision 60 ft."],"ac":23,"ac_touch":16,"ac_flat_footed":18,"ac_mods":"+1 deflection, +4 Dex, +1 dodge, +4 natural, +3 shield","hp":102,"hd":"4d10+8d8+44","hd_value":12,"fort":9,"ref":14,"will":7,"defensive_abilities":["evasion","improved uncanny dodge","trap sense +2"],"immunities":["charm","sleep"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +14 (1d8+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack +4d6 plus slow reactions"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect thoughts"}]}],"strength":18,"dexterity":18,"constitution":14,"intelligence":15,"wisdom":12,"charisma":17,"baseatk":10,"cmb":14,"cmd":30,"feats":[{"feat":"Combat Expertise"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Feint"},{"feat":"Mobility"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":22},{"skill":"Diplomacy","value":18},{"skill":"Disable Device","value":19},{"skill":"Disguise","value":22},{"skill":"Knowledge (local)","value":13},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":19},{"skill":"Use Magic Device","value":18}],"languages":["Common"],"sq":["change shape (alter self )","mimicry","perfect copy","rogue talents  (combat trick, slow reactions, stand up, surprise attack)","trapfinding"],"gear":"+2 buckler, ring of protection +1","during_combat":"If her disguise is found out, Zevanxus assumes her true form to attack with her claws, relying on Improved Feint in order to maximize her sneak attack opportunities.","morale":"Zevanxus abandons her experiment on Guxer if reduced to fewer than 30 hit points, attempting to escape into the crowded streets, nurse her wounds, and perhaps plot vengeance against the PCs.","source":"AP 30, Pathfinder RPG Bestiary 89"},{"name":"Varpnall","cr":11,"xp":12800,"race":"otyugh","gender":"Male","age_category":"Adult","alignment":"N","size":"Huge","type":"aberration","templates_applied":"advanced, plague bearer","init":5,"senses":["darkvision 60 ft.","scent"],"ac":22,"ac_touch":9,"ac_flat_footed":21,"ac_mods":"+1 Dex, +13 natural, -2 size","hp":159,"hd":"11d8+110","hd_value":11,"fort":12,"ref":4,"will":10,"immunities":["disease"],"speed":[{"type":"land","speed":20}],"melee":"bite +16 (2d8+10 plus disease), 2 tentacles +14 (2d6+5 plus disease and grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"tentacle, 2d6+5"},{"type":"disease cloud"},{"type":"diseased"},{"type":"diseased flesh"}],"strength":30,"dexterity":12,"constitution":28,"intelligence":9,"wisdom":17,"charisma":10,"baseatk":8,"cmb":20,"cmd":31,"feats":[{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (bite, tentacles)"},{"feat":"Multiattack"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Escape Artist","value":15},{"skill":"Perception","value":17},{"skill":"Stealth","value":7,"special":"+8 in lair"}],"languages":["Common","Infernal"],"sq":["carrier","quick incubation"],"special_abilities":[{"type":"Carrier","kind":"Ex","details":"Although he is immune to the debilitating effects of disease, Varpnall can still carry infections and continues to do so regardless of magical healing."},{"type":"Disease Cloud","kind":"Ex","details":"Varpnall's diseased breath fills an invisible 30-foot-radius cloud around him. All breathing creatures in this area must make two DC 24 Fortitude saves to avoid contracting bubonic plague and mindfire."},{"type":"Diseased","kind":"Ex","details":"Varpnall is swimming in pestilence. His attacks, breath, and flesh all carry disease. Any time Varpnall strikes a foe with his bite or a tentacle, he exposes the victim to two diseases: filth fever and leprosy. The creature struck must make two DC 24 Fortitude saves, one against each disease, to resist infection. These diseases function similarly to those of the same name listed on page 557 of the Pathfinder RPG Core Rulebook. The save DCs for all of these diseases is Constitution-based."},{"type":"Diseased Flesh","kind":"Ex","details":"Any creature that uses a bite attack against Varpnall or consumes any of the otyugh's flesh is exposed to blinding sickness. A DC 24 Fortitude save negates the infection."},{"type":"Quick Incubation","kind":"Su","details":"Any diseases inflicted by Varpnall have no onset time-the first effects of the diseases manifest immediately."}],"during_combat":"Varpnall is quick to anger, but not quick to attack. If he has to move to attack a foe, he uses Vital Strike with his bite attack, then proceeds with standard full attacks on following rounds.","morale":"Varpnall surrenders if brought below 30 hp, waving his tentacles in fear and staggering back into a corner as he begs for mercy. He'll give up all of his treasure if necessary to purchase his life from the PCs.","source":"AP 30, Pathfinder RPG Bestiary 223,  Advanced Bestiary 194"},{"name":"Hellknight","cr":5,"xp":1600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":5},{"class":"Hellknight","level":1}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":20,"ac_touch":11,"ac_flat_footed":19,"ac_mods":"+9 armor, +1 Dex","hp":62,"hd":"6d10+29","hd_value":6,"fort":10,"ref":2,"will":4,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":20}],"melee":"+1 longsword +12 (1d8+7/19-20)","ranged":"mwk composite longbow +8 (1d8+3/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"smite chaos","details":"1/day, +1 attack, damage, and AC"},{"type":"weapon training","details":"heavy blades +1"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect chaos"}]}],"strength":16,"dexterity":12,"constitution":16,"intelligence":8,"wisdom":13,"charisma":10,"baseatk":5,"cmb":8,"cmd":19,"feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (longsword)"},{"feat":"Weapon Specialization (longsword)"}],"skills":[{"skill":"Intimidate","value":9},{"skill":"Perception","value":10}],"languages":["Common"],"sq":["armor training 1","aura of law"],"special_abilities":[{"type":"Aura of Law","kind":"Ex","details":"The power of a Hellknight's aura of law is equal to his Hellknight level."},{"type":"Detect Chaos","kind":"Sp","details":"At will, a Hellknight can use detect chaos, as the spell, in the same manner as a paladin using her detect evil ability."},{"type":"Smite Chaos","kind":"Su","details":"As a swift action once per day, a Hellknight can smite chaos. This grants the Hellknight a bonus to hit a chaotic target equal to his Wisdom modifier (if any) and adds his Hellknight level to all damage rolls against chaotic targets. If the target is an outsider with the chaotic subtype, a chaotic-aligned aberration, or a fey creature, the bonus to damage increases to 2 points of damage per class level the Hellknight possesses. Regardless of the target, smite chaos attacks automatically bypass any DR the chaotic creature might possess. In addition, while smite chaos is in effect, the Hellknight gains a deflection bonus equal to his Wisdom modifier (if any) to his AC against attacks made by the target of the smite. The smite effect remains until the target is dead or the next time the Hellknight rests and regains the use of this ability."}],"gear":"full plate, +1 longsword, masterwork composite longbow (+3 Str) with 20 arrows","during_combat":"If a chaotic target is obvious, a Hellknight generally attacks it instead of other targets. Hellknights work together to flank foes and support each other, favoring melee combat over ranged if a choice is possible.","morale":"Hellknights fight to the death.","source":"AP 30, Pathfinder Adventure Path #27 66"},{"name":"Paralictor Gonville Chard","cr":8,"xp":4800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"Hellknight","level":2},{"class":"ranger","level":7}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"init_special":"+2 urban","ac":20,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+10 armor","hp":74,"hd":"9d10+25","hd_value":9,"fort":9,"ref":7,"will":7,"speed":[{"type":"land","speed":20}],"melee":"+1 longsword +15 (1d8+7/19-20)","ranged":"+1 composite longbow +15 (1d8/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"Human +4, native  outsider +2"},{"type":"hunter's bond","details":"companions"},{"type":"smite chaos","details":"1/day, +1 attack and AC, +2 damage"}],"spell_like_abilities_caster_level":2,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect chaos"},{"spell":"discern lies"}]}],"spellsprepared_caster_level":4,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"longstrider"},{"spell":"resist energy"}]}],"strength":18,"dexterity":10,"constitution":14,"intelligence":8,"wisdom":12,"charisma":14,"baseatk":9,"cmb":13,"cmd":23,"feats":[{"feat":"Endurance"},{"feat":"Heavy Armor Proficiency"},{"feat":"Iron Will"},{"feat":"Point Blank Shot"},{"feat":"Precise Shot"},{"feat":"Two-Weapon Defense"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (longbow)"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Diplomacy","value":11},{"skill":"Intimidate","value":14},{"skill":"Knowledge (local)","value":8},{"skill":"Knowledge (nobility)","value":3},{"skill":"Linguistics","value":0},{"skill":"Perception","value":13,"special":"+2 urban"},{"skill":"Ride","value":4}],"languages":["Common","Infernal"],"sq":["aura of law","favored terrain (urban +2)","hellknight armor 1","track  +3","wild empathy +9","woodland stride"],"special_abilities":[{"type":"Discern Lies","kind":"Sp","details":"When Gonville use his detect chaos ability on a target, he can determine if that creature is lying. This effect functions similarly to discern lies, but he can detect multiple lies from multiple creatures through one use of detect chaos. In addition, he must be able to hear and understand what a creature within the area of effect is saying to discern lies."},{"type":"Hellknight Armor","kind":"Ex","details":"Gonville's armor is specially made full plate that displays his power and status in the Hellknight Order of the Rack. His armor check penalty in this armor is 1 less than normal and his maximum Dexterity bonus to AC is increased by 1."}],"gear":"+1 full plate, +1 longsword, +1 composite longbow with 20 arrows, cloak of resistance +1","during_combat":"Gonville Chard fights with his longsword in both hands. When fighting those he deems criminals (and not mindless or ravaging monsters) he takes care to strike for nonlethal damage on his final blows so that he can capture the criminal alive for trial rather than accidentally kill him.","morale":"Gonville Chard fights to the death.","source":"AP 30, Pathfinder Adventure Path #27 66"},{"name":"Blacknapes","cr":5,"xp":1600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":4},{"class":"rogue","level":2}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+4 armor, +1 Dex, +1 dodge, +2 shield","hp":53,"hd":"4d10+2d8+22","hd_value":6,"fort":8,"ref":5,"will":2,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","evasion"],"speed":[{"type":"land","speed":30}],"melee":"unarmed strike +9 (1d3+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":16,"dexterity":13,"constitution":14,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":5,"cmb":8,"cmb_special":"+10 grapple","cmd":20,"cmd_special":"22 vs. grapple","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Grapple"},{"feat":"Improved Unarmed Strike"},{"feat":"Toughness"},{"feat":"Weapon Focus (unarmed strike)"},{"feat":"Weapon Specialization (unarmed strike)"}],"skills":[{"skill":"Intimidate","value":8},{"skill":"Perception","value":10},{"skill":"Profession (sailor)","value":10},{"skill":"Sleight of Hand","value":10},{"skill":"Swim","value":12}],"languages":["Common"],"sq":["armor training 1","rogue talent (combat trick)","trapfinding"],"gear":"+1 studded leather, +1 buckler, potion of cure moderate wounds (2), oil of taggit (3 doses)","during_combat":"The Blacknapes have long histories of fisticuffs, and prefer this as their primary weapon. They'll gang up on foes to enable sneak attacks, and are fond of grappling enemies and holding them down while other thugs punch and kick them into submission.","morale":"A Blacknape is a coward at heart, and flees if reduced to 20 hit points or less.","source":"AP 30"},{"name":"Outraged Nobles","cr":4,"xp":1200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"aristocrat","level":6}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":11,"ac_touch":11,"ac_flat_footed":11,"ac_mods":"+1 deflection","hp":21,"hd":"6d8-6","hd_value":6,"fort":3,"ref":2,"will":5,"speed":[{"type":"land","speed":30}],"melee":"dagger +3 (1d4-1/19-20) or club +3 (1d6-1)","space":"5 ft.","reach":"5 ft.","strength":8,"dexterity":10,"constitution":9,"intelligence":12,"wisdom":11,"charisma":16,"baseatk":4,"cmb":3,"cmd":14,"feats":[{"feat":"Deceitful"},{"feat":"Great Fortitude"},{"feat":"Persuasive"},{"feat":"Skill Focus (Bluff)"}],"skills":[{"skill":"Appraise","value":10},{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":14},{"skill":"Disguise","value":0},{"skill":"Intimidate","value":0},{"skill":"Knowledge (local)","value":10},{"skill":"Knowledge (nobility)","value":10},{"skill":"Perception","value":9},{"skill":"Ride","value":9}],"languages":["Common","Infernal","Osiriani"],"gear":"dagger, ring of protection +1","during_combat":"While not particularly skilled, the outraged nobles can certainly help the PCs set up flanking opportunities or get in the way of assassins. They can also use the aid another action to aid a PC's attack roll or AC.","morale":"While outraged at the attack, the nobles are not particularly brave. They drop their weapons as soon as they take any damage and attempt to flee.","source":"AP 30"},{"name":"Rolan","cr":7,"xp":3200,"race":"dwarf","gender":"Male","age_category":"Adult","classes":[{"class":"expert","level":9}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["dwarf"],"init":5,"senses":["darkvision 60 ft."],"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+2 armor, +1 Dex","hp":67,"hd":"9d8+27","hd_value":9,"fort":8,"ref":4,"will":6,"save_mods":"+2 vs. poison, spells, and spell-like abilities","defensive_abilities":["defensive training"],"speed":[{"type":"land","speed":20}],"melee":"mwk club +7 (1d6)","ranged":"mwk light crossbow +8 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hatred"}],"strength":10,"dexterity":12,"constitution":16,"intelligence":13,"wisdom":10,"charisma":15,"baseatk":6,"cmb":6,"cmd":17,"cmd_special":"21 vs. bull rush or trip","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Magical Aptitude"},{"feat":"Master Craftsman"},{"feat":"Skill Focus (Use Magic Device)"}],"skills":[{"skill":"Appraise","value":13,"special":"+2 nonmagical metals or gemstones"},{"skill":"Craft (weaponsmithing)","value":13},{"skill":"Disable Device","value":18},{"skill":"Knowledge (arcana)","value":13},{"skill":"Knowledge (engineering)","value":13},{"skill":"Profession (tinkerer)","value":12},{"skill":"Spellcraft","value":15},{"skill":"Use Magic Device","value":19}],"languages":["Common","Azlanti","Dwarven"],"gear":"+1 padded armor, masterwork club, masterwork light crossbow with 20 bolts, goggles of minute seeing","during_combat":"Once combat begins, Rolan orders his toys to attack his foes while he hangs back to support the constructs with his crossbow, firing at the nearest enemy. He switches to his club only if he has no other option.","morale":"Once three or more of his toys have been destroyed, Rolan becomes aggressive in combat, pursuing his foes with a psychotic fervor. If all of his constructs are defeated, he drops his weapon and falls to his knees in tears-as long as any of his constructs remain functional, he fights to the death.","source":"AP 30"},{"name":"Roland's Toy","cr":3,"xp":800,"race":"animated object","age_category":"Adult","alignment":"N","size":"Medium","type":"construct","init":0,"senses":["darkvision 60 ft.","low-light vision"],"ac":16,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+6 natural","hp":36,"hd":"3d10+20","hd_value":3,"fort":1,"ref":1,"will":-4,"defensive_abilities":["hardness 10"],"immunities":["construct traits"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"slam +5 (1d6+3 plus grab)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":10,"wisdom":1,"charisma":1,"baseatk":3,"cmb":5,"cmd":15,"skills":[{"skill":"Swim","value":10}],"during_combat":"These constructs follow Rolan's shouted commands, but aren't very good about following them for long, as they often switch targets to attack the last foe who struck them.","morale":"Roland's toys fight to the death.","source":"AP 30, Pathfinder RPG Bestiary 14"},{"name":"Thesing the Vampire","cr":11,"xp":12800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"expert","level":3},{"class":"rogue","level":7}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human"],"templates_applied":"vampire","init":7,"senses":["darkvision 60 ft."],"ac":31,"ac_touch":15,"ac_flat_footed":27,"ac_mods":"+5 armor, +1 deflection, +3 Dex, +1 dodge, +7 natural, +4 shield","hp":102,"hd":"10d8+50","hd_value":10,"hp_mods":"fast healing 5","fort":8,"ref":12,"will":8,"defensive_abilities":["channel resistance +4","evasion","trap sense +2","uncanny dodge"],"dr":"10/magic and silver","immunities":["undead traits"],"resists":["cold 10","electricity 10"],"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"+3 rapier +15 (1d6+7/18-20), slam +6 (1d4+4 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain"},{"type":"children of the night"},{"type":"create spawn"},{"type":"dominate","details":"DC 19"},{"type":"energy drain","details":"2 levels, DC 19"},{"type":"sneak attack","details":"+4d6"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"2/day","spells":[{"spell":"shield"}]},{"frequency":"3/day","spells":[{"spell":"bleed"}]}],"strength":18,"dexterity":17,"intelligence":13,"wisdom":10,"charisma":19,"baseatk":7,"cmb":11,"cmd":26,"feats":[{"feat":"Alertness"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Skill Focus (Perform act)"},{"feat":"Skill Focus (Perform sing)"},{"feat":"Spring Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Bluff","value":25},{"skill":"Disguise","value":17},{"skill":"Intimidate","value":17},{"skill":"Knowledge (local)","value":14},{"skill":"Knowledge (nobility)","value":14},{"skill":"Linguistics","value":5},{"skill":"Perception","value":25},{"skill":"Perform (act)","value":23},{"skill":"Perform (sing)","value":23},{"skill":"Ride","value":15},{"skill":"Sense Motive","value":0},{"skill":"Stealth","value":23}],"languages":["Common","Infernal"],"sq":["change shape (dire bat or wolf, beast shape II)","gaseous  form","rogue talents (major magic [shield], minor magic [bleed],  weapon training)","shadowless","spider climb","trapfinding"],"gear":"+1 chain shirt, amulet of natural armor +1, belt of incredible dexterity +2, cloak of resistance +1, ring of protection +1","before_combat":"Thesing casts shield on himself before entering combat.","during_combat":"Thesing attacks with his rapier in one hand and a secondary attack with his slam. He makes full uses of his stealth and the ability to become gaseous to flee combat and go into hiding every few rounds, only to spring out of the shadows to sneak attack a victim over and over.","morale":"If reduced to 0 hp, Thesing becomes gaseous and flees to area N8. If confronted there, the vampire fights to the death.","source":"AP 30, Pathfinder RPG Bestiary 270"},{"name":"Vampire Spawn","cr":4,"xp":1200,"race":"Vampire Spawn","gender":"Female","age_category":"Adult","alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented humanoid"],"init":5,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":11,"ac_flat_footed":4,"ac_mods":"+1 Dex, +4 natural","hp":30,"hd":"4d8+12","hd_value":4,"hp_mods":"fast healing 2","fort":3,"ref":2,"will":5,"defensive_abilities":["channel resistance +2"],"dr":"5/silver","immunities":["undead traits"],"resists":["cold 10","electricity 10"],"weaknesses":["resurrection vulnerability","vampire  weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"slam +4 (1d4+1 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain"},{"type":"dominate","details":"DC 14"},{"type":"energy drain","details":"1  level, DC 14"}],"strength":12,"dexterity":12,"intelligence":11,"wisdom":13,"charisma":15,"baseatk":3,"cmb":4,"cmd":15,"feats":[{"feat":"Improved Initiative"},{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":9},{"skill":"Knowledge (local)","value":7},{"skill":"Perception","value":11},{"skill":"Stealth","value":16}],"languages":["Common"],"sq":["gaseous form","shadowless","spider climb"],"during_combat":"Eager to slay the PCs, the vampire spawn focus their attacks on the same foe, hoping to overwhelm enemies one at a time with energy drains.","morale":"The vampire spawn fight until destroyed.","source":"AP 30, Pathfinder RPG Bestiary 271"},{"name":"Ara Verennie","cr":12,"xp":19200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":11}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human","incorporeal"],"templates_applied":"ghost","init":2,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":19,"ac_flat_footed":24,"ac_mods":"+4 armor, +6 deflection, +2 Dex, +1 dodge, +4 shield","hp":126,"hd":"11d6+88","hd_value":11,"fort":9,"ref":5,"will":8,"save_mods":"+4 vs. poison","defensive_abilities":["channel resistance +4","incorporeal","rejuvenation"],"immunities":["undead traits"],"resists":["fire 10"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +5 (12d6; DC 21)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"corrupting gaze","details":"DC 21"},{"type":"malevolence","details":"DC 21"},{"type":"telekinesis","details":"DC 21"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"hellfire"}]},{"frequency":"7/day","spells":[{"spell":"corrupting touch"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":11,"spellsknown_concentration":17,"spellsknown":[{"spell_level":5,"spell_slots":5,"spells":[{"spell":"dismissal"},{"spell":"dominate person"},{"spell":"summon monster V"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"charm monster"},{"spell":"dimension door"},{"spell":"summon monster IV"},{"spell":"wall of fire"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"fly"},{"spell":"stinking cloud"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"acid arrow"},{"spell":"glitterdust"},{"spell":"invisibility"},{"spell":"scorching ray"},{"spell":"summon monster II"},{"spell":"web"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"charm person"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"bloodline":"infernal","dexterity":14,"intelligence":14,"wisdom":12,"charisma":22,"baseatk":5,"cmb":5,"cmd":24,"feats":[{"feat":"Augment Summoning"},{"feat":"Combat Casting"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Extend Spell"},{"feat":"Greater Spell Focus (conjuration)"},{"feat":"Spell Focus (conjuration)"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Fly","value":17},{"skill":"Intimidate","value":20},{"skill":"Knowledge (arcana)","value":16},{"skill":"Knowledge (planes)","value":9},{"skill":"Perception","value":9},{"skill":"Spellcraft","value":16},{"skill":"Stealth","value":10}],"languages":["Common","Infernal"],"sq":["bloodline arcana"],"before_combat":"Ara casts mage armor, shield, protection from good, and invisibility as soon as she realizes someone intrudes upon her lair.","during_combat":"Ara doesn't engage the PCs directly at first. She remains invisible and uses her summoning spells to summon numerous Medium earth elementals that look like skeletal Hellknights to attack the PCs. She attempts to use malevolence on the most attractive PC if she can arrange to be alone in a room with that character-if successful, she poses as the PC for as long as possible to learn what she can about the PCs before reporting to Chammady in hopes of being granted leave to take her hijacked body through the well of many worlds to experience Hell. If discovered, she prefers to use her spells and corrupting gaze at range, using her flight to stay out of melee.","morale":"Ara fights until destroyed, but unless the dagger is removed from her body and her remains are returned to Paralictor Chard, she rejuvenates in 2d4 days and resumes her blasphemies.","source":"AP 30, Pathfinder RPG Bestiary 144"},{"name":"Skarx Veskandi","cr":11,"xp":12800,"race":"Tiefling","gender":"Female","age_category":"Adult","classes":[{"class":"monk","level":12}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["native"],"init":4,"senses":["darkvision 60 ft."],"ac":28,"ac_touch":21,"ac_flat_footed":23,"ac_mods":"+3 armor, +1 deflection, +4 Dex, +1 dodge, +3 monk, +4 natural, +2 Wis","hp":114,"hd":"12d8+60","hd_value":12,"fort":11,"ref":12,"will":10,"save_mods":"+2 vs. enchantment","defensive_abilities":["improved evasion"],"immunities":["disease","poison"],"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":70}],"melee":"unarmed strike +13 (2d6+2) or flurry of blows +14 (2d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"flurry of blows"},{"type":"stunning fist","details":"12/day, DC 18,  fatigued, sickened, staggered"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"fog cloud"}]}],"strength":14,"dexterity":18,"constitution":16,"intelligence":10,"wisdom":15,"charisma":6,"baseatk":9,"cmb":14,"cmd":30,"feats":[{"feat":"Dodge"},{"feat":"Fiendish Heritage"},{"feat":"Gorgon's Fist"},{"feat":"Improved Unarmed Strike"},{"feat":"Medusa's Wrath"},{"feat":"Mobility"},{"feat":"Scorpion Style"},{"feat":"Spring Attack"},{"feat":"Stunning Fist"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":19,"special":"+28 jump"},{"skill":"Bluff","value":0},{"skill":"Intimidate","value":13},{"skill":"Perception","value":17},{"skill":"Profession (sailor)","value":17},{"skill":"Stealth","value":6}],"languages":["Common","Infernal"],"sq":["abundant step","fast movement","high jump","ki pool (8  points, lawful, magic)","maneuver training","slow fall 60  ft.","still mind","wholeness of body (12 hit points)"],"special_abilities":[{"type":"Fiendish Heritage","details":"Skarx's fiendish heritage feat marks her as a devilspawn Tiefling-her base ability score modifiers are +2 Con, +2 Wis, and -2 Cha, unlike standard tieflings, and she gains fog cloud instead of darkness as a spell-like ability."}],"gear":"belt of incredible dexterity +2, bracers of armor +3, ring of protection +1, potion of fly, potion of barkskin +4","before_combat":"Skarx drinks both of her potions before combat begins if she has a chance.","during_combat":"Skarx does her best to maintain mobility in combat, using Spring Attack and Vital Strike to hit enemies while staying out of melee herself.","morale":"If reduced to 30 hp or less, Skarx surrenders and begs for her life, offering Chammady's location in return for her freedom. If the PCs strike this deal and release her as she begs, she flees to Ecarrdian's side and could be encountered at the Vacant Throne. If confronted there, she fights to the death.","source":"AP 30, Pathfinder RPG Bestiary 264"},{"name":"Hellcat","cr":7,"xp":3200,"race":"Hellcat","age_category":"Adult","alignment":"LE","size":"Large","type":"outsider","sub_types":["evil","extraplanar","lawful"],"init":9,"senses":["darkvision 60 ft.","scent"],"ac":21,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+5 Dex, +1 dodge, +6 natural, -1 size","hp":85,"hd":"9d10+36","hd_value":9,"fort":7,"ref":10,"will":5,"defensive_abilities":["invisible in light"],"dr":"5/good","resists":["fire 10"],"sr":17,"speed":[{"type":"land","speed":40}],"melee":"2 claws +13 (1d6+5 plus grab), bite +13 (2d6+5)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws 1d6+5"}],"strength":21,"dexterity":21,"constitution":19,"intelligence":10,"wisdom":14,"charisma":10,"baseatk":9,"cmb":15,"cmd":31,"cmd_special":"35 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"}],"skills":[{"skill":"Acrobatics","value":17,"special":"+4 jump"},{"skill":"Climb","value":17},{"skill":"Perception","value":18},{"skill":"Stealth","value":17},{"skill":"Survival","value":14},{"skill":"Swim","value":17}],"languages":["Infernal (cannot speak)","telepathy 100 ft."],"special_abilities":[{"type":"Invisible in Light","kind":"Su","details":"In bright light, a hellcat is naturally invisible. In normal light, a hellcat has partial concealment (20% miss chance), while in dim light it has no special concealment. Darkness smothers the creature's flickering glow and conceals it normally."}],"during_combat":"The hellcats themselves choose their targets, letting their devilish riders concentrate solely on slashing at foes with their glaives.","morale":"The hellcats fight to the death.","source":"AP 30"},{"name":"Vuiper Ghivel","cr":13,"xp":25600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"aristocrat","level":7},{"class":"cleric of Abadar","level":7}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":17,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+4 armor, +2 deflection, +1 Dex","hp":126,"hd":"14d8+63","hd_value":14,"fort":10,"ref":5,"will":15,"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +10 (1d4-1/19-20)","ranged":"+1 keen light crossbow +13 (1d8+1/17-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"4/day, 4d6, DC 14"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"inspiring word"},{"spell":"resistant touch"}]}],"spellsprepared_caster_level":7,"spellsprepared_concentration":12,"spellsprepared":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"discern lies","type":"domain"},{"spell":"freedom of movement"},{"spell":"poison"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"blindness/deafness"},{"spell":"cure serious wounds"},{"spell":"dispel magic"},{"spell":"protection from energy","type":"domain"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds","count":2},{"spell":"enthrall","type":"domain"},{"spell":"hold person"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"cure light wounds","count":3},{"spell":"detect chaos"},{"spell":"divine favor","type":"domain"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"light"},{"spell":"mending"},{"spell":"read magic"}]}],"spelldomains":"Nobility, Protection","strength":8,"dexterity":13,"constitution":16,"intelligence":10,"wisdom":20,"charisma":12,"baseatk":10,"cmb":9,"cmd":22,"feats":[{"feat":"Combat Casting"},{"feat":"Deadly Aim"},{"feat":"Persuasive"},{"feat":"Point Blank Shot"},{"feat":"Rapid Reload"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (light crossbow)"}],"skills":[{"skill":"Diplomacy","value":22},{"skill":"Intimidate","value":22},{"skill":"Knowledge (local)","value":7},{"skill":"Knowledge (nobility)","value":8},{"skill":"Knowledge (religion)","value":7},{"skill":"Linguistics","value":4},{"skill":"Spellcraft","value":17}],"languages":["Common","Infernal"],"sq":["aura"],"gear":"+2 leather armor, +1 keen light crossbow, masterwork dagger, cape of the mountebank, headband of inspired wisdom +2, ring of protection +2, gold holy symbol worth 250 gp","before_combat":"If the PCs give him time to prepare, Vuiper casts discern lies, freedom of movement, and protection from energy (fire) before he answers his door to talk to them.","during_combat":"Vuiper tries to keep his distance in combat, using channeled negative energy or his spells to keep the PCs at range as long as possible while fighting a retreat to area T9 where he can yell downstairs for aid. Chammady won't reply, which forces Vuiper to use his cape of the mountebank to flee to her side, likely forcing her to join the fray. If Vuiper attacks first, this is the final straw on his teetering faith-Abadar doesn't approve and immediately strips the man of his spells and ability to channel negative energy. In this event, a panicked Vuiper falls back on his crossbow and makes haste to join Chammady for protection. If the PCs attack Vuiper first, though, his faith isn't broken and he retains access to his spells and abilities, as he can convince himself he's only acting in self-defense.","morale":"If brought below 40 hit points, Vuiper drops his weapons and begs for mercy. He holds nothing back from the PCs, asking them only to be merciful to his lover when they confront her.","source":"AP 30"},{"name":"Chammady Drovenge","cr":14,"xp":38400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"assassin","level":4},{"class":"ranger","level":10}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"init_special":"+4 urban","ac":29,"ac_touch":18,"ac_flat_footed":24,"ac_mods":"+8 armor, +3 deflection, +5 Dex, +3 natural","hp":125,"hd":"10d10+4d8+52","hd_value":14,"fort":11,"ref":14,"will":7,"save_mods":"+2 vs. poison","defensive_abilities":["evasion","uncanny dodge"],"resists":["fire 10"],"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":40}],"melee":"+3 returning Human bane dagger +17 (1d4+6/17-20), assassin's dagger +16 (1d4+5/17-20)","ranged":"+3 returning Human bane dagger +21 (1d4+3/17-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death attack","details":"DC 12"},{"type":"favored enemy","details":"Human +6, halfling +4, dwarf +2"},{"type":"hunter's bond","details":"companions"},{"type":"sneak attack","details":"+2d6"},{"type":"true death","details":"DC 19"}],"spellsprepared_caster_level":7,"spellsprepared_concentration":8,"spellsprepared":[{"spell_level":2,"spell_slots":1,"spells":[{"spell":"barkskin"}]},{"spell_level":1,"spell_slots":3,"spells":[{"spell":"longstrider"},{"spell":"pass without trace"},{"spell":"resist energy"}]}],"strength":16,"dexterity":20,"constitution":16,"intelligence":10,"wisdom":12,"charisma":14,"baseatk":13,"cmb":16,"cmd":34,"feats":[{"feat":"Deadly Aim"},{"feat":"Double Slice"},{"feat":"Endurance"},{"feat":"Greater Two-Weapon Fighting"},{"feat":"Improved Critical (dagger)"},{"feat":"Improved Iron Will"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Two-Weapon Fighting"},{"feat":"Two-Weapon Rend"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":26,"special":"+4 jump"},{"skill":"Bluff","value":19},{"skill":"Diplomacy","value":19},{"skill":"Disguise","value":7},{"skill":"Fly","value":10},{"skill":"Knowledge (nobility)","value":5},{"skill":"Linguistics","value":4},{"skill":"Perception","value":18,"special":"+4 urban"},{"skill":"Stealth","value":31,"special":"+4 urban"},{"skill":"Survival","value":16,"special":"+4 urban"}],"languages":["Common","Infernal"],"sq":["favored terrain (urban +4, water +2)","hidden weapons","poison use","swift tracker","track +5","wild empathy +12","woodland stride"],"special_abilities":[{"type":"Enhanced NPC","details":"As Chammady's stats are built using a 20-point buy and her gear is equivalent to a PC of her level, her CR is +1 higher than normal."}],"gear":"+4 glamered mithral chain shirt, +3 returning Human bane dagger, assassin's dagger, belt of physical perfection +2, ring of chameleon power, ring of protection +3, sandals of elvenkind, well of many worlds, wings of flying, gold signet ring worth 1,200 gp, mithral earrings worth 800 gp","before_combat":"Chammady casts all of her spells before entering combat, using resist energy to gain resistance to fire.","during_combat":"Chammady has rarely met a foe that could match her grace and deadly skill in combat, with the exception of her brother and perhaps the devil Melavengian. This has left her somewhat proud and arrogant-once combat begins, she makes a death attack against a foe if she has the chance, but she prefers straight-up combat so she can \"show off.\" She fights with her two deadly daggers, focusing on Human foes if possible and using Improved Vital Strike and Two-Weapon Rend to maximize damage.","morale":"Chammady is no coward, yet neither are her convictions as overwhelming as her brother's. If reduced to 30 or fewer hit points, she tries to escape.","source":"AP 30"},{"name":"Melavengian","cr":14,"xp":38400,"race":"barbed devil","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of Mammon","level":7}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":11,"senses":["darkvision 60 ft.","see in darkness"],"ac":30,"ac_touch":20,"ac_flat_footed":23,"ac_mods":"+3 deflection, +7 Dex, +10 natural","hp":218,"hd":"12d10+7d8+121","hd_value":19,"fort":18,"ref":17,"will":20,"defensive_abilities":["barbed defense (1d8+8)"],"dr":"10/good Immune fire, poison","resists":["acid 10","cold 10"],"sr":22,"speed":[{"type":"land","speed":30}],"melee":"2 claws +28 (2d8+10/19-20 plus fear and grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative  energy","details":"8/day, 4d6, DC 18"},{"type":"fear","details":"DC 21"},{"type":"impale 3d8+12"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"hold person"},{"spell":"major image"},{"spell":"produce flame"},{"spell":"pyrotechnics"},{"spell":"scorching ray","details":"2 rays only"}]},{"frequency":"1/day","spells":[{"spell":"order's wrath"},{"spell":"summon","details":"1 barbed devil  35%, level 4"},{"spell":"unholy blight"}]},{"frequency":"8/day","spells":[{"spell":"acid dart"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":7,"spellsprepared_concentration":12,"spellsprepared":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"air walk"},{"spell":"poison"},{"spell":"spike stones","type":"domain"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"cure serious wounds"},{"spell":"dispel magic"},{"spell":"locate object"},{"spell":"stone shape","type":"domain"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds","count":3},{"spell":"soften earth and stone","type":"domain"},{"spell":"status"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cure light wounds","count":3},{"spell":"divine favor"},{"spell":"obscuring mist"},{"spell":"protection from good","type":"domain"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"mending"}]}],"spelldomains":"Earth, Evil","strength":26,"dexterity":25,"constitution":22,"intelligence":10,"wisdom":20,"charisma":20,"baseatk":17,"cmb":25,"cmd":45,"feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Appraise","value":22},{"skill":"Bluff","value":27},{"skill":"Diplomacy","value":18},{"skill":"Knowledge (planes)","value":13},{"skill":"Knowledge (religion)","value":13},{"skill":"Perception","value":17},{"skill":"Stealth","value":19}],"languages":["Common","Celestial","Draconic","Infernal","telepathy 100 ft."],"gear":"amulet of mighty fists +2, ring of protection +3","before_combat":"Melavengian maintains a status spell on both Ecarrdian and Chammady at all times. Before combat begins, he casts air walk and protection from good on himself.","during_combat":"Melavengian prefers to open combat at range, beginning with scorching rays, hold person, and spike stones to soften up the foes before he moves in to attack. Just before entering melee, he casts divine favor and then uses his claws to ruin foes.","morale":"Melavengian fights to the death.","source":"AP 30, Pathfinder RPG Bestiary 72"},{"name":"Ecarrdian Drovenge","cr":15,"xp":51200,"race":"Tiefling","gender":"Male","age_category":"Adult","classes":[{"class":"duelist","level":4},{"class":"rogue","level":10}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["native"],"templates_applied":"advanced","init":7,"senses":["darkvision 60 ft."],"ac":31,"ac_touch":22,"ac_flat_footed":21,"ac_mods":"+7 armor, +2 deflection, +9 Dex, +1 dodge, +2 natural","hp":189,"hd":"10d8+4d10+122","hd_value":14,"fort":14,"ref":19,"will":10,"defensive_abilities":["canny defense","enhanced mobility","grace","improved evasion","improved uncanny dodge","parry","trap sense +3"],"dr":"10/good and silver","resists":["cold 5","electricity 5","fire 5"],"sr":26,"speed":[{"type":"land","speed":40}],"melee":"rapier of puncturing +19 (1d6+10/15-20 plus wounding)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"Combat Reflexes"},{"type":"precise strike"},{"type":"sneak attack +5d6 plus 5 bleed"}],"strength":18,"dexterity":20,"constitution":24,"intelligence":18,"wisdom":16,"charisma":14,"baseatk":11,"cmb":15,"cmd":33,"feats":[{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Improved Critical (rapier)"},{"feat":"Improved Feint"},{"feat":"Improved Vital Strike"},{"feat":"Mobility"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Acrobatics","value":22,"special":"+9 jump"},{"skill":"Bluff","value":21},{"skill":"Disable Device","value":22},{"skill":"Escape Artist","value":22},{"skill":"Intimidate","value":19},{"skill":"Knowledge (local)","value":21},{"skill":"Knowledge (nobility)","value":9},{"skill":"Knowledge (planes)","value":9},{"skill":"Perception","value":20},{"skill":"Perform (dance)","value":7},{"skill":"Sense Motive","value":20},{"skill":"Sleight of Hand","value":22},{"skill":"Stealth","value":24}],"languages":["Common","Azlanti","Draconic","Infernal","Osiriani"],"sq":["improved reaction +2","rogue talents (bleeding attack, combat trick, finesse rogue, improved evasion, weapon training)","trapfinding +5"],"special_abilities":[{"type":"Spawn of Mammon","kind":"Ex","details":"As the spawn of Mammon, Ecarrdian's base ability score modifiers are +2 Con, +2 Wis, and -2 Cha. Ecarrdian has the Advanced Creature template, a 20-point ability score buy, and gear as if he were a PC. In addition, while Ecarrdian doesn't possess the standard darkness spell-like ability of a Tiefling, he possesses exceptional DR and SR. These benefits increase his CR by +2."}],"gear":"+5 leather armor, rapier of puncturing, amulet of proof against detection and location, belt of mighty constitution +4, boots of striding and springing, bracelet of friends (keyed to Chammady), cloak of resistance +3, ring of freedom of movement, ring of protection +2","before_combat":"Ecarrdian uses his bracelet of friends to call Chammady as soon as he fears combat with the PCs is imminent.","during_combat":"Ecarrdian prefers to attack once per round, using Improved Feint and Improved Vital Strike to maximize his damage and (unless he's finding it difficult to hit his foes) Combat Expertise to increase his AC. Only if he's surrounded does he make full-attack actions.","morale":"Ecarrdian fights to the death.","source":"AP 30, Pathfinder RPG Bestiary 264, 294"},{"name":"Happs Bydon","cr":0.5,"xp":200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":1}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 armor, +2 Dex","hp":11,"hd":"1d10+6","hd_value":1,"fort":4,"ref":4,"will":1,"speed":[{"type":"land","speed":30}],"melee":"dagger +3 (1d4+2/19-20)","ranged":"composite longbow +3 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"elf +2"}],"strength":14,"dexterity":15,"constitution":15,"intelligence":8,"wisdom":12,"charisma":10,"baseatk":1,"cmb":3,"cmd":15,"feats":[{"feat":"Point-Blank Shot"},{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":4},{"skill":"Knowledge (nature)","value":3},{"skill":"Perception","value":5},{"skill":"Ride","value":6},{"skill":"Stealth","value":6},{"skill":"Survival","value":5}],"languages":["Common"],"sq":["track +1","wild empathy +1"],"gear":"leather armor, dagger, composite longbow (+2 Str) with 20 arrows, 2 days of trail rations, silver Stag Lord amulet worth 20 gp, 35 gp, alchemist's fire (2)","during_combat":"Happs is overconfident and enjoys boasting during battle, calling out attacks and hollow threats that he's ill-equipped to carry out. As a battle progresses, if his insults and threats continue to fail, he grows increasingly grim and quiet. He prefers to fight with his longbow, letting his men take the risks in melee. He uses his alchemist's fire against PCs in a tight group, or perhaps as a distraction against the stables to draw the PCs out of combat and into firefighting or controlling panicked horses.","morale":"Happs knows that his position as second-in-command is tenuous at best and won't back down from a fight in front of his men-as long as one other bandit can see him, he fights to the death. If all other bandits are slain, Happs flees or surrenders immediately if he's taken any damage (or immediately upon suffering any damage otherwise).","source":"AP 31"}];
